(6172681, 911282, 40391, '<td valign="top">So many figurines in this challenge. But, this one has been taken with photography in mind and not just a snap shot. Nice!</td>', 'So many figurines in this challenge. But, this one has been taken with photography in mind and not just a snap shot. Nice!', '2010-09-27 09:53:48.000000', NULL, 1),
(6172683, 911325, 40391, '<td valign="top">I expected so many fungi shots that I decided not to even try. But I''ve come across none until now and that doesn''t matter because this is not only a great find but so very well photographed. I love it! 9.</td>', 'I expected so many fungi shots that I decided not to even try. But I''ve come across none until now and that doesn''t matter because this is not only a great find but so very well photographed. I love it! 9.', '2010-09-27 09:56:58.000000', NULL, 1),
(6172684, 911352, 40391, '<td valign="top">the concept is simple enough.  But the composition, lighting, processing and especially the model is above par!  Lovely, 8.</td>', 'the concept is simple enough.  But the composition, lighting, processing and especially the model is above par!  Lovely, 8.', '2010-09-27 09:58:55.000000', NULL, 1),
(6172686, 911278, 40391, '<td valign="top">Can''t tell if the bird is alive or not, but it is so well captured that it gives me that fantisy feel. 8.</td>', 'Can''t tell if the bird is alive or not, but it is so well captured that it gives me that fantisy feel. 8.', '2010-09-27 10:02:55.000000', NULL, 1),
