(6172688, 910890, 40391, '<td valign="top">You know you had a great shot when you took this I''m sure! Fantastic!! 9</td>', 'You know you had a great shot when you took this I''m sure! Fantastic!! 9', '2010-09-27 10:05:00.000000', NULL, 1),
